local config = {
  ui_story_31730401_1_dialog_content = "All of the banquet's guests have been accounted for.",
  ui_story_31730401_2_dialog_content = "The entertainment devices in each of the guest rooms are inspected as well.",
  ui_story_31730401_3_dialog_content = "Every room has been stocked with 23 different types of cakes, as well as 86 different types of tea.",
  ui_story_31730401_4_dialog_content = "Directions to the banquet hall have also been posted on the doors of every room.",
  ui_story_31730401_5_dialog_content = "Security has finished performing a thorough safety inspection.",
  ui_story_31730401_6_dialog_content = "Master and Miss Nina should be taking their afternoon nap at this time...",
  ui_story_31730401_7_dialog_content = "Which means I now have the perfect opportunity to root out those who have wronged the Andersen family.",
  ui_story_31730401_8_dialog_content = "This should be the street. From there, turn left at the first intersection, then walk four doors down, the second building on the west side.",
  ui_story_31730401_9_dialog_content = "That's the <color=#FFB400>Gray</color> residence. I accepted a job request from the <color=#FFB400>Steelshafts</color> there a few days ago.",
  ui_story_31730401_10_dialog_content = "Apparently, Gray's one of the Steelshafts that plans to <color=#FFB400>raid the Andersen Mansion</color> on the night that Androma Andersen makes his announcement.",
  ui_story_31730401_11_dialog_content = "As far as I know, the Steelshafts don't have that many in their ranks, so they rely on cunning to beat their enemies.",
  ui_story_31730401_12_dialog_content = "Even though time is on your side, I suggest you be cautious about their plans before making your move.",
  ui_story_31730401_13_dialog_content = "You have my sincerest gratitude, Mr. Nekoyashiki.",
  ui_story_31730401_14_dialog_content = "*Cough* The uh... formalities aren't necessary.",
  ui_story_31730401_15_dialog_content = "This is the place.",
  ui_story_31730401_16_dialog_content = "*Coughing*... It appears that no matter how many times I come here, I can never get accustomed to the dust in the air.",
  ui_story_31730401_17_dialog_content = "Mr. Gray?",
  ui_story_31730401_18_dialog_content = "Ngh...",
  ui_story_31730401_19_dialog_content = "Booze! More booze...",
  ui_story_31730401_20_dialog_content = "\"Booze\"? I will gladly pour you a drink, sir. But would you mind opening the door first, please?",
  ui_story_31730401_21_dialog_content = "Slam!",
  ui_story_31730401_22_dialog_content = "Wha...? Where's the booze?! Ngh... There's no booze?!",
  ui_story_31730401_23_dialog_content = "How dare you lie to me! I'm with the Steelshafts, don'tcha know?!",
  ui_story_31730401_24_dialog_content = "Mr. Gray, please open your eyes wide and take a good look at who I am.",
  ui_story_31730401_25_dialog_content = "I don't give a damn who you are—",
  ui_story_31730401_X25_dialog_content = "Ah!",
  ui_story_31730401_X26_dialog_content = "I didn't ask you to kneel, Mr. Gray.",
  ui_story_31730401_26_dialog_content = "S-Sir!",
  ui_story_31730401_27_dialog_content = "You're here, sir!",
  ui_story_31730401_28_dialog_content = "I'm beggin' you! Just gimme two more days—no, one! I'll take care of it by tonight, I swear!",
  ui_story_31730401_29_dialog_content = "I'll have more money by tonight! I just need a little more time, and I can pay you back in full, with interest!",
  ui_story_31730401_X29_dialog_content = "Please! I'm tellin' the truth, I swear!",
  ui_story_31730401_30_dialog_content = "And I'm sure you are, Mr. Gray.",
  ui_story_31730401_31_dialog_content = "But the sight of you weeping and writhing on the floor... is quite unbecoming.",
  ui_story_31730401_32_dialog_content = "Not to mention, your tears have stained my leather shoes...",
  ui_story_31730401_33_dialog_content = "Ah, but please don't worry about that.",
  ui_story_31730401_34_dialog_content = "Urgh!",
  ui_story_31730401_35_dialog_content = "Your back makes for a good cleaning cloth.",
  ui_story_31730401_36_dialog_content = "Tonight... tonight, sir! I promise!",
  ui_story_31730401_37_dialog_content = "Shh... Just listen, Mr. Gray.",
  ui_story_31730401_38_dialog_content = "As a purveyor of Umbraton's finest spirits, my extensive network of informants is the only thing vaster than my knowledge of drinks.",
  ui_story_31730401_39_dialog_content = "I'm perfectly aware of your plans to raid the Andersen Mansion tonight.",
  ui_story_31730401_40_dialog_content = "But before doing so, surely you will be gathering with the rest of the Steelshafts somewhere, yes?",
  ui_story_31730401_41_dialog_content = "Let me guess... Someone in the Steelshafts has already given you the rendezvous location for this operation, yes?",
  ui_story_31730401_42_dialog_content = "Sir, I-I'm not sure I understand.",
  ui_story_31730401_43_dialog_content = "Look me in the eyes when I'm speaking to you, Mr. Gray.",
  ui_story_31730401_44_dialog_content = "All you need to do is give me the location, and I'll tear up your loan slip here and now.",
  ui_story_31730401_45_dialog_content = "B-But if I do that, the Steelshafts will come after my head—!",
  ui_story_31730401_46_dialog_content = "I could always resort to the punishment written on your contract, instead?",
  ui_story_31730401_47_dialog_content = "Though I'd think that a quick death would be far more acceptable, wouldn't you agree?",
  ui_story_31730401_48_dialog_content = "P-Please, sir, just one more night...",
  ui_story_31730401_49_dialog_content = "You misunderstand, Mr. Gray.",
  ui_story_31730401_50_dialog_content = "You have exactly three seconds to give me the information I require.",
  ui_story_31730401_51_dialog_content = "Three—",
  ui_story_31730401_52_dialog_content = "O-Okay! I'll talk!",
  ui_story_31730401_53_dialog_content = "I'll talk...",
  ui_story_31730401_54_dialog_content = "The Steelshafts will gather near Maida Mesa's ruins, in an abandoned house with three crooked trees planted in the courtyard.",
  ui_story_31730401_55_dialog_content = "I see. Thank you for your gracious cooperation.",
  ui_story_31730401_56_dialog_content = "W-Wait, I don't understand...",
  ui_story_31730401_57_dialog_content = "Why do you want this information instead of the money I owe you?",
  ui_story_31730401_58_dialog_content = "You appeared out of nowhere a month ago with the intent to sell me rare and expensive spirits...",
  ui_story_31730401_59_dialog_content = "So why...",
  ui_story_31730401_60_dialog_content = "No... Y-You... You!",
  ui_story_31730401_61_dialog_content = "You knew the Steelshafts had hired me, didn't you?",
  ui_story_31730401_62_dialog_content = "The booze, the crazy debt, and now this visit...",
  ui_story_31730401_63_dialog_content = "You did all of that just so you could find out their gathering spot!",
  ui_story_31730401_64_dialog_content = "You misunderstand, Mr. Gray.",
  ui_story_31730401_65_dialog_content = "I acquired their location long ago. I simply came here to confirm it.",
  ui_story_31730401_66_dialog_content = "Now, please have a seat and rest for a while.",
  ui_story_31730401_67_dialog_content = "I'll need to rummage through your dresser for a suitable costume, if you don't mind...",
  ui_story_31730401_68_dialog_content = "Hmmm, this will do.",
  ui_story_31730401_69_dialog_content = "Hey! You new around here?",
  ui_story_31730401_70_dialog_content = "Yeah.",
  ui_story_31730401_71_dialog_content = "Have you confirmed his identity? And did he get the secret signal right?",
  ui_story_31730401_72_dialog_content = "Yes, boss! He got everything right!",
  ui_story_31730401_73_dialog_content = "Huh. What was your name again? Gray, wasn't it?",
  ui_story_31730401_74_dialog_content = "Yeah.",
  ui_story_31730401_75_dialog_content = "You're taller than I expected, but I guess that doesn't matter.",
  ui_story_31730401_76_dialog_content = "Is everyone here yet?",
  ui_story_31730401_77_dialog_content = "Yes, boss!",
  ui_story_31730401_78_dialog_content = "Alright, all of you, listen up! It's time for me to unveil our plan.",
  ui_story_31730401_79_dialog_content = "I'm only saying it once, so listen closely! Once I'm done talking, we're gonna grab all the contraband here and make our way to the next rendezvous point!",
  ui_story_31730401_80_dialog_content = "I had a few outfits custom-made to look like the ones worn by the Andersen family's servants. We'll be wearing those as disguises to get in.",
  ui_story_31730401_81_dialog_content = "And remember, our target tonight is Nina Andersen, and Nina Andersen only!",
  ui_story_31730401_82_dialog_content = "Don't get distracted by any of the expensive crap lying around the Andersen Mansion! Once we have our hostage, get the hell out of there!",
  ui_story_31730401_X82_dialog_content = "And if any of you makes even the smallest mistake... Well, you know what's coming for ya.",
  ui_story_31730401_X83_dialog_content = "I didn't waste all these years in Umbraton for nothing.",
  ui_story_31730401_83_dialog_content = "With Androma's beloved daughter in our custody, I'm sure he'll pay any price to get her back.",
  ui_story_31730401_84_dialog_content = "We'll go over the infiltration and everyone's specific role at the next rendezvous point.",
  ui_story_31730401_85_dialog_content = "Did I make myself clear, lads? If so, grab as much of this contraband as you can carry and move out!",
  ui_story_31730401_86_dialog_content = "Hmm, crystal clear indeed.",
  ui_story_31730401_87_dialog_content = "I must say...",
  ui_story_31730401_88_dialog_content = "If I knew how simple and idiotic your plan was from the beginning, I never would have personally come here.",
  ui_story_31730401_89_dialog_content = "Huh? What the hell are you talking about, Gray?",
  ui_story_31730401_90_dialog_content = "Well, you see...",
  ui_story_31730401_91_dialog_content = "I'm not Mr. Gray, but rather, I am Minos, the Andersen family's exclusive butler.",
  ui_story_31730401_92_dialog_content = "Honesly, even speaking the name of the Andersen family in such a slovenly place is a shameless insult to Master's good name.",
  ui_story_31730401_93_dialog_content = "Damn it!",
  ui_story_31730401_94_dialog_content = "Get him, you clods! Whatever happens, we can't let this guy leave here alive!",
  ui_story_31730401_95_dialog_content = "Take this!",
  ui_story_31730401_96_dialog_content = "Your punches are severely lacking in grace.",
  ui_story_31730401_97_dialog_content = "Out of the way, guys! I'm letting off an incendiary!",
  ui_story_31730401_98_dialog_content = "And you, your aim is quite pitiful. Next time, fixing up that ghastly hairstlye of yours before shooting might help a little.",
  ui_story_31730401_99_dialog_content = "Damn you... I'll just use my sword instead! I'm gonna cut you down!!",
  ui_story_31730401_100_dialog_content = "Ah, my apologies, but what I'm about to say might hurt your pride.",
  ui_story_31730401_101_dialog_content = "Your swordsmanship can't even begin to compare to that of my master's daughter. Even PlayerName would have no trouble defeating you.",
  ui_story_31730401_X101_dialog_content = "You useless lot!",
  ui_story_31730401_102_dialog_content = "Forget about him! Just grab the stuff and go!",
  ui_story_31730401_103_dialog_content = "Good thing I came prepared. I'm the only one who knows exactly where the next meeting point is!",
  ui_story_31730401_104_dialog_content = "Six on the roof, ten outside the house, and... fifteen inside the house.",
  ui_story_31730401_105_dialog_content = "Just as I predicted, more or less.",
  ui_story_31730401_106_dialog_content = "In that case... I believe it's time to end this little game.",
  ui_story_31730401_107_dialog_content = "With such an important event to attend to tonight, I really wished to avoid soiling my hands with the stench of vermin...",
  ui_story_31730401_108_dialog_content = "But as vermin are wont to scurry away, I suppose I must finish this quickly and wash off the stench when I return.",
  ui_story_31730401_109_dialog_content = "Then again, as a proud butler, I'm always happy to clean things up.",
  ui_story_31730401_110_dialog_content = "So please, don't be afraid... I'm actually quite gentle.",
  ui_story_31730401_111_dialog_content = "The first step in maintaining a neat and tidy home—",
  ui_story_31730401_112_dialog_content = "—is to gather all of the garbage and properly dispose of it.",
  ui_story_31730401_113_dialog_content = "Greetings, PlayerName, and welcome again to my master's home.",
  ui_story_31730401_114_dialog_content = "Did you rest adequately in your room? Were the refreshments and entertainment devices to your liking?",
  ui_story_31730401_115_option_content = "Absolutely!",
  ui_story_31730401_116_dialog_content = "Just the answer I wanted to hear.",
  ui_story_31730401_117_dialog_content = "Er, Minos...? Are you feeling okay? You don't look very well...",
  ui_story_31730401_118_option_content = "Yeah, but...",
  ui_story_31730401_119_dialog_content = "You look exhausted, Minos.",
  ui_story_31730401_120_dialog_content = "You must have been really busy today.",
  ui_story_31730401_121_dialog_content = "Not at all.",
  ui_story_31730401_122_dialog_content = "My apologies if my appearance gave you cause for concern.",
  ui_story_31730401_123_dialog_content = "To worry our esteemed guests is one of the worst things a butler could do.",
  ui_story_31730401_124_dialog_content = "Perhaps I should use some ladies' cosmetics to brighten up my appearance?",
  ui_story_31730401_125_dialog_content = "I-I had no idea you had such, um... vanity, Minos.",
  ui_story_31730401_126_dialog_content = "Oh, I'm only kidding.",
  ui_story_31730401_127_dialog_content = "Now then, Mr. Navigator, please make your way to the banquet hall and enjoy your meal.",
  ui_story_31730401_128_dialog_content = "Unfortunately, I still have other matters to attend to.",
  ui_story_31730401_129_dialog_content = "Before the feast begins in earnest, I must make an urgent report to my master.",
  ui_story_31730401_130_dialog_content = "If you require anything at all, please don't hesitate to ask any of the servants. I shall rejoin you and the others momentarily.",
  ui_story_31730401_131_dialog_content = "Sure, I can take care of myself, don't worry.",
  ui_story_31730401_132_dialog_content = "It is my great honor to have you all as guests in my home tonight.",
  ui_story_31730401_133_dialog_content = "As you have all most likely heard by now, yes... I do have a small announcement to make.",
  ui_story_31730401_134_dialog_content = "Nothing earth-shattering, by any means. Rather, it's simply the affirmation of a new direction in which the Andersen family will grow.",
  ui_story_31730401_135_dialog_content = "Ladies and gentlemen, it is my pleasure to announce—",
  ui_story_31730401_136_dialog_content = "From this day forward, the Andersen family will officially enter the real estate industry!",
  ui_story_31730401_137_dialog_content = "Congratulations! Congratulations, Androma!",
  ui_story_31730401_138_dialog_content = "Is this the power of the old nobility?",
  ui_story_31730401_139_dialog_content = "It seems every single guest room has been stocked with all kinds of refreshments and recreation facilities... If I didn't know better, I'd say we were still in Lumopolis!",
  ui_story_31730401_140_dialog_content = "And with this small announcement out of the way, I ask that you please enjoy everything our banquet offers.",
  ui_story_31730401_141_dialog_content = "What was that? Did you hear that just now?",
  ui_story_31730401_142_dialog_content = "Was that an explosion?",
  ui_story_31730401_143_dialog_content = "Yes, I believe I heard it as well...",
  ui_story_31730401_144_dialog_content = "Don't get ahead of yourselves! Master Androma most likely ordered fireworks for tonight!",
  ui_story_31730401_145_dialog_content = "Well, should we go outside and see?",
  ui_story_31730401_146_dialog_content = "I suppose we should... It does sound like fireworks, after all.",
  ui_story_31730401_147_dialog_content = "Has all of the contraband been taken care of?",
  ui_story_31730401_148_dialog_content = "Yes, Master.",
  ui_story_31730401_149_dialog_content = "I've arranged for someone to set off the fireworks. Miss Nina is also quite insistent on seeing them.",
  ui_story_31730401_150_dialog_content = "I see. Well done, Minos.",
  ui_story_31730401_151_dialog_content = "Oh, and the wine you provided for us today is absolutely exquisite.",
  ui_story_31730401_152_dialog_content = "How very gracious of you to say so, Master... But this is all part of my duty as your humble butler.",
  ui_story_31730401_153_dialog_content = "Careful, Miss Nina. Don't stay out too long, lest you catch a cold!",
  ui_story_31730401_154_dialog_content = "I know, I know!",
  ui_story_31730401_155_dialog_content = "Oh, and Minos?",
  ui_story_31730401_156_dialog_content = "When will the haunted house be ready? I bought all sorts of props for it!",
  ui_story_31730401_157_dialog_content = "Soon, Miss.",
  ui_story_31730401_158_dialog_content = "Trust me—I mean, very soon.",
  ui_story_31730601_1_dialog_content = "Temporarily... closed...",
  ui_story_31730601_2_dialog_content = "No—!",
  ui_story_31730601_3_dialog_content = "I've been shopping here all along. How could it suddenly... be closed...",
  ui_story_31730601_4_dialog_content = "Oh? Isn't this Mr. Navigator?",
  ui_story_31730601_5_dialog_content = "I heard a scream just now and came over to check. Are you in some kind of trouble?",
  ui_story_31730601_6_dialog_content = "Ah... Sorry for disturbing you. It's actually not a big deal.",
  ui_story_31730601_7_dialog_content = "The shop where I always used to buy from suddenly closed, leaving me clueless about where to shop now.",
  ui_story_31730601_8_dialog_content = "Businesses in Umbraton come and go all the time. They often have to close up shop for one reason or another.",
  ui_story_31730601_9_dialog_content = "Therefore, it's advisable for you not to sign up for the membership, as there's a high chance of being swindled.",
  ui_story_31730601_10_dialog_content = "... It's not like I have enough money to sign up for the membership.",
  ui_story_31730601_11_dialog_content = "What would you like to purchase?",
  ui_story_31730601_12_dialog_content = "Hmm... I want to buy some wrapping paper and ribbons to prepare for the holiday.",
  ui_story_31730601_13_dialog_content = "Oh? In that case, I happen to know a place for you.",
  ui_story_31730601_14_dialog_content = "Please allow me to lead the way for you.",
  ui_story_31730601_15_dialog_content = "That's very nice of you. Have you just finished shopping too? With all the bags here...",
  ui_story_31730601_16_dialog_content = "Right, yes. I've been to several stores, trying to choose the most cost-effective items.",
  ui_story_31730601_17_dialog_content = "Please don't worry. We're indeed on the way. The weather has been humid lately, so I need to buy some insect-repellent incense.",
  ui_story_31730601_18_dialog_content = "Otherwise... I'm afraid you'll find it amusing. The young lady might throw a tantrum again.",
  ui_story_31730601_19_dialog_content = "No, no... Let me give you a little help!",
  ui_story_31730601_20_dialog_content = "Thank you for your kindness then.",
  ui_story_31730601_21_dialog_content = "Wow, all the goods in the bags have actually been sorted already?",
  ui_story_31730601_22_dialog_content = "You really do cover all bases as a butler.",
  ui_story_31730601_23_dialog_content = "It's almost as if you were born to be a butler. It's hardly like...",
  ui_story_31730601_24_dialog_content = "You mean a killer?",
  ui_story_31730601_25_dialog_content = "Ah, sorry... I think I got a little carried away...",
  ui_story_31730601_26_dialog_content = "No worries, someone has said this about me before...",
  ui_story_31730601_27_dialog_content = "We've still got a long way to go. Want to hear some stories from my past?",
  ui_story_31730601_28_dialog_content = "Of course!",
  ui_story_31730601_29_dialog_content = "Thinking back, it was her who saved my life...",
  ui_story_31730601_30_dialog_content = "<color=#e8d9bb>Ka-thunk!!</color>",
  ui_story_31730601_31_dialog_content = "Hmph, what a stubborn bull to tame...",
  ui_story_31730601_32_dialog_content = "Were you the one who wiped out eight of my guys?",
  ui_story_31730601_33_dialog_content = "I've come with a gift from the master, and this is how you repay his kindness...?",
  ui_story_31730601_34_dialog_content = "How disgraceful. You should be ashamed to call yourselves allies of the family!",
  ui_story_31730601_35_dialog_content = "Kindness? Allies? No, if you live here, you should know that we don't bother with such things.",
  ui_story_31730601_36_dialog_content = "Power is everything, we don't need a weak family.",
  ui_story_31730601_37_dialog_content = "How dare you make such greedy and shameless speak?",
  ui_story_31730601_38_dialog_content = "Heh, I'll show you all—",
  ui_story_31730601_39_dialog_content = "?!",
  ui_story_31730601_40_dialog_content = "Take him down!",
  ui_story_31730601_41_dialog_content = "D-Don't let him get close to the boss!",
  ui_story_31730601_42_dialog_content = "Betrayal and treachery... That's the real weakness!",
  ui_story_31730601_43_dialog_content = "... Almost.",
  ui_story_31730601_44_dialog_content = "Such a pitiful fool. Any killer knows that the best way to stay alive is to join the stronger party.",
  ui_story_31730601_45_dialog_content = "Do whatever you want, I don't care...",
  ui_story_31730601_46_dialog_content = "I'm not you... I would never betray the master and the young lady.",
  ui_story_31730601_47_dialog_content = "Then if I brought you to the negotiation with the Andersens...",
  ui_story_31730601_48_dialog_content = ".. and show your master what a sorry sight you've become?",
  ui_story_31730601_49_dialog_content = "You—!",
  ui_story_31730601_50_dialog_content = "Shut him up, then put him into the case he brought.",
  ui_story_31730601_51_dialog_content = "Yes!",
  ui_story_31730601_52_dialog_content = "Since the Andersens gave me a gift, I should return the gesture.",
  ui_story_31730601_53_dialog_content = "Beast! I should kill you... I should have... Urgh!!!",
  ui_story_31730601_54_dialog_content = "<color=#e8d9bb>Just like that, I was stuffed into the case and placed in a carriage.</color>",
  ui_story_31730601_55_dialog_content = "<color=#e8d9bb>They were rushing, but they stopped. Maybe there was a crash or something, or another gang.</color>",
  ui_story_31730601_56_dialog_content = "<color=#e8d9bb>I struggle to roll out of the carriage but can't open the case.</color>",
  ui_story_31730601_57_dialog_content = "<color=#e8d9bb>Then, I felt weak hands give the case I was in a shaky push...</color>",
  ui_story_31730601_58_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_31730601_59_dialog_content = "...",
  ui_story_31730601_60_dialog_content = "It's not some dirty money or jewelry from the gang...",
  ui_story_31730601_61_dialog_content = "I've disappointed you, haven't I?",
  ui_story_31730601_62_dialog_content = "...!",
  ui_story_31730601_63_dialog_content = "I thought it was just some kitten or puppy, but... but...",
  ui_story_31730601_64_dialog_content = "The world is a tapestry of unexpected events.",
  ui_story_31730601_65_dialog_content = "If you don't want to get into trouble, you better leave...",
  ui_story_31730601_66_dialog_content = "I... I know...",
  ui_story_31730601_67_dialog_content = "<color=#e8d9bb>Rumble—</color>",
  ui_story_31730601_68_dialog_content = "...?!",
  ui_story_31730601_69_dialog_content = "What are you going to do... Why are you still pushing me around?!",
  ui_story_31730601_70_dialog_content = "You'd be dead if I left you here, wouldn't you?",
  ui_story_31730601_71_dialog_content = "I know of an underground hospital that specializes in treating people like you.",
  ui_story_31730601_72_dialog_content = "I'll take you there, but as for what happens next... I really wouldn't know...",
  ui_story_31730601_73_dialog_content = "Knowing who I am, you still want to save me?",
  ui_story_31730601_74_dialog_content = "I-I don't like the smell of blood on you...",
  ui_story_31730601_75_dialog_content = "But even with such a strong smell of blood, I can still catch the scent of flour and butter on you.",
  ui_story_31730601_76_dialog_content = "Those real gangsters... They reek of pipes, cheap liquor, and casinos.",
  ui_story_31730601_77_dialog_content = "So you're like a cook or a butler, a good kid who got stuck in this mess, right?",
  ui_story_31730601_78_dialog_content = "That was a sharp lady.",
  ui_story_31730601_79_dialog_content = "And under those circumstances... it's truly admirable.",
  ui_story_31730601_80_dialog_content = "Ah, we've arrived. This is the place.",
  ui_story_31730601_81_dialog_content = "Is this your friend, young Mr. Butler?",
  ui_story_31730601_82_dialog_content = "He's a close friend, and it's the first time he has come here, so would you mind giving us a discount?",
  ui_story_31730601_83_dialog_content = "No problem, of course... a close friend of young Mr. Butler.",
  ui_story_31730601_84_dialog_content = "N-Nice to meet you.",
  ui_story_31730601_85_dialog_content = "*sniffing*",
  ui_story_31730601_86_dialog_content = "Huh... Do I, do I have a certain smell on me?",
  ui_story_31730601_87_dialog_content = "Ah, sorry, my eyesight isn't very good, so I tend to remember customers by their scent.",
  ui_story_31730601_88_dialog_content = "You... You smell like the sky.",
  ui_story_31730601_89_dialog_content = "It's so clear, bright, and forward-thinking. It's a breath of fresh air.",
  ui_story_31730601_90_dialog_content = "It goes so well with the buttery, floury scent of young Mr. Butler.",
  ui_story_31730601_91_dialog_content = "Do you work at the Shuttle Hub?",
  ui_story_31730601_92_dialog_content = "I have bouquets and aromatherapy suitable for airships. Would you like to make a purchase?",
  ui_story_31730601_93_dialog_content = "Yes, please. I do need some of those.",
  ui_story_31730601_94_dialog_content = "... So this the lady who saved you?",
  ui_story_31730601_95_dialog_content = "Yes, after all, it was a life-saving favor. She helped me escape and return to the Andersens.",
  ui_story_31730601_96_dialog_content = "Now that she's older, I often come to see her.",
  ui_story_31730601_97_dialog_content = "And you brought me here...",
  ui_story_31730601_98_option_content = "So that I can understand you better?",
  ui_story_31730601_99_dialog_content = "Oh, I didn't expect you to understand things this way.",
  ui_story_31730601_100_dialog_content = "But in a way, yes. My past is inextricably linked to the family's history of bloodshed.",
  ui_story_31730601_101_dialog_content = "And sharing with you something I've never told anyone before truly brings me a sense of relief.",
  ui_story_31730601_102_option_content = "So that I can keep her company too?",
  ui_story_31730601_103_dialog_content = "Of course, she would probably be even happier with more people around.",
  ui_story_31730601_104_dialog_content = "And this is also my first time bringing someone who knows about this matter to her place.",
  ui_story_31730601_105_dialog_content = "You've also come to know one of my secrets.",
  ui_story_31730601_106_dialog_content = "It would be my greatest honor.",
  ui_story_31730601_107_dialog_content = "Anyway, this is a wonderful place, feel free to make your selection here.",
  ui_story_31730601_108_dialog_content = "Thank you, I'm sure I'll find something I like here!"
}
